export const appScript = "import { buildHealthReport, buildQuestionReport } from '/health-model.js';\nconst state={company:{name:'美的集团',thscode:'000333.SZ'},bundle:null,range:60,question:'美的集团增长还稳吗，为什么？'};\nconst $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',\"'\":'&#39;','\"':'&quot;'}[c]));\nconst num=v=>Number.isFinite(Number(v))?Number(v):null, fmt=(v,d=2)=>num(v)===null?'—':num(v).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d}), pct=v=>num(v)===null?'—':`${num(v)>=0?'+':''}${fmt(v,1)}%`, money=v=>num(v)===null?'—':num(v)>=1e8?`${fmt(num(v)/1e8,2)}亿`:`${fmt(num(v)/1e4,0)}万`;\nasync function api(path){const r=await fetch(path,{headers:{accept:'application/json'}}),b=await r.json().catch(()=>({error:{message:'服务器响应无法读取'}}));if(!r.ok)throw new Error(b.error?.message||`HTTP ${r.status}`);return b}\nasync function searchStocks(){const q=$('stock-search').value.trim();if(!q)return;const box=$('search-results');box.hidden=false;box.innerHTML='<div class=\"search-result\">正在查找…</div>';try{const result=await api(`/api/search?q=${encodeURIComponent(q)}`);if(result.items.length===1){const x=result.items[0];selectCompany(x.thscode,x.name||x.ticker);return}box.innerHTML=result.items.length?result.items.map(x=>`<button class=\"search-result\" data-code=\"${x.thscode}\" data-name=\"${esc(x.name||x.ticker)}\"><b>${esc(x.name||x.ticker)}</b><span>${x.thscode}</span></button>`).join(''):'<div class=\"search-result\">没有找到 A 股公司</div>'}catch(e){box.innerHTML=`<div class=\"search-result\">查找失败：${esc(e.message)}</div>`}}\nfunction loading(){const box=$('global-status');box.className='loading-box';box.innerHTML='<i></i><div><strong>正在生成体检报告</strong><p>同步核对行情、历史价格和财务报表…</p></div>';$('freshness').textContent='实时数据更新中'}\nasync function loadResearch(){loading();try{state.bundle=await api(`/api/research?thscode=${encodeURIComponent(state.company.thscode)}`);renderAll();const partial=Object.values(state.bundle.modules).some(x=>x.status!=='ok');$('global-status').className=`loading-box ${partial?'warning':'hidden'}`;if(partial)$('global-status').innerHTML='<div><strong>部分证据暂不可用</strong><p>已保留未知项，没有使用模拟数据补齐。</p></div>'}catch(e){console.error('research request failed',e);$('global-status').className='loading-box error';$('global-status').innerHTML='<div><strong>暂时无法生成体检</strong><p>数据服务没有连接成功。我们没有用旧数据冒充最新结果。</p></div>';$('core-answer').textContent='数据连接失败，当前不能可靠回答这个问题。';$('causal-chain').innerHTML='<article class=\"cause-node unknown\"><div class=\"cause-index\">!</div><div><span>还没有答案</span><h3>证据尚未取得</h3><p>请稍后更新数据。系统不会用旧数据或猜测补齐结论。</p></div></article>';$('next-action-text').textContent='先恢复数据连接，再重新生成这家公司的一分钟体检。';$('freshness').textContent='数据连接失败'}}\nfunction chartPath(points,w,h,pad){if(!points.length)return '';const vals=points.map(p=>p.close_price),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1;return points.map((p,i)=>`${i?'L':'M'}${pad+i*(w-2*pad)/Math.max(points.length-1,1)},${h-pad-(p.close_price-min)*(h-2*pad)/span}`).join(' ')}\nfunction renderPriceChart(){const m=state.bundle.modules.market,s=m.signals||{},points=(s.series||[]).slice(-state.range),svg=$('price-chart');if(!points.length){svg.innerHTML='<text x=\"450\" y=\"170\" text-anchor=\"middle\">价格历史暂不可用</text>';return}const w=900,h=340,p=42,path=chartPath(points,w,h,p),vals=points.map(x=>x.close_price),min=Math.min(...vals),max=Math.max(...vals),area=`${path} L${w-p},${h-p} L${p},${h-p} Z`;svg.innerHTML=`<defs><linearGradient id=\"fill\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#176b56\" stop-opacity=\".22\"/><stop offset=\"1\" stop-color=\"#176b56\" stop-opacity=\"0\"/></linearGradient></defs>${[0,.5,1].map(t=>`<line x1=\"${p}\" x2=\"${w-p}\" y1=\"${p+t*(h-2*p)}\" y2=\"${p+t*(h-2*p)}\"/><text x=\"4\" y=\"${p+4+t*(h-2*p)}\">${fmt(max-t*(max-min),1)}</text>`).join('')}<path class=\"chart-area\" d=\"${area}\"/><path class=\"chart-line\" d=\"${path}\"/>`;$('market-metrics').innerHTML=[[`20 日平均价`,s.ma20,'观察短期趋势'],['60 日平均价',s.ma60,'观察中期趋势'],['120 日平均价',s.ma120,'观察较长期趋势'],['近 20 日平均成交额',money(s.averageTurnover20),'观察交易活跃度']].map(([a,b,c])=>`<div><span>${a}</span><b>${b??'—'}</b><small>${c}</small></div>`).join('')}\nconst period=r=>r?.period_end_ms||r?.period_end||r?.end_date_ms||null,pick=(r,keys)=>{for(const k of keys)if(r?.[k]!=null)return Number(r[k]);return null};\nconst indicatorNames={calculate_operating_income_yoy_growth_ratio:'营业收入同比增长',calculate_operating_profit_yoy_growth_ratio:'营业利润同比增长',total_assets_growth_ratio:'总资产增长',fixed_asset_invest_expansion_ratio:'固定资产投入扩张',calculate_parent_holder_net_profit_yoy_growth_ratio:'归母净利润同比增长',total_assets_net_ratio:'总资产净利率',index_deduct_weighted_avg_roe:'扣非净资产收益率',sale_gross_margin:'毛利率',sale_net_interest_ratio:'销售净利率',index_weighted_avg_roe:'净资产收益率',current_ratio:'流动比率',cash_ratio:'现金比率',quick_ratio:'速动比率',earned_interest_multiple:'利息保障倍数',assets_debt_ratio:'资产负债率',total_assets_turnover_ratio:'总资产周转率',inventory_turnover_ratio:'存货周转率',long_term_debt_equity_ratio:'长期负债与权益比',current_assets_turnover_ratio:'流动资产周转率',receive_account_turnover_ratio:'应收账款周转率',net_profit_cash_content:'每百元利润对应经营现金',cash_operating_index:'现金经营质量',operating_cash_flow_net_divide_income:'经营现金占收入比例',cash_meet_invest_ratio:'现金满足投资比例'};\nfunction renderFinancial(){const f=state.bundle.modules.financials,periods=[...new Set([...(f.income||[]),...(f.balance||[]),...(f.cashflow||[])].map(period).filter(Boolean))].sort((a,b)=>b-a).slice(0,8),at=(rows,p)=>(rows||[]).find(r=>period(r)===p)||{},rows=[['营业收入',p=>pick(at(f.income,p),['operating_income'])],['归母净利润',p=>pick(at(f.income,p),['parent_holder_net_profit'])],['经营现金流',p=>pick(at(f.cashflow,p),['act_cash_flow_net'])],['总资产',p=>pick(at(f.balance,p),['assets_total'])],['总负债',p=>pick(at(f.balance,p),['total_debt'])]];$('financial-table').innerHTML=periods.length?`<table><thead><tr><th>看什么</th>${periods.map(p=>`<th>${new Date(p).toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit'})}</th>`).join('')}</tr></thead><tbody>${rows.map(([n,get])=>`<tr><td>${n}</td>${periods.map(p=>`<td>${money(get(p))}</td>`).join('')}</tr>`).join('')}</tbody></table>`:'<p>财务表暂不可用。</p>';const abilities=state.bundle.modules.indicators.data?.abilities||[];$('indicator-groups').innerHTML=abilities.map(g=>`<article><h4>${({growth:'增长能力',profitability:'盈利能力',solvency:'偿债能力',operation:'经营效率','cash-flow':'现金质量'})[g.ability]||g.ability}</h4>${(g.indicators||[]).slice(0,5).map(i=>`<div><span>${indicatorNames[i.index_id]||'专业指标'}</span><b>${i.value??'—'}</b><small>${esc(i.index_id)}</small></div>`).join('')}</article>`).join('')}\nfunction renderLineage(){const names={market:'行情与历史价格',financials:'三张财务报表',indicators:'财务指标'};$('lineage-grid').innerHTML=Object.entries(state.bundle.modules).map(([k,m])=>`<article><header><h4>${names[k]}</h4><span class=\"${m.status}\">${m.status==='ok'?'已取得':'不完整'}</span></header><p>来源：同花顺扶摇金融数据 API</p><details><summary>查看请求编号</summary>${(m.requestIds||[]).map(id=>`<code>${esc(id)}</code>`).join('')||'<span>暂无成功请求</span>'}</details></article>`).join('')}\nfunction renderQuestionReport(){const report=buildQuestionReport(state.bundle,state.company,state.question),health=buildHealthReport(state.bundle,state.company),m=state.bundle.modules.market,q=m.snapshot||{};$('company-name').textContent=state.company.name;$('company-code').textContent=state.company.thscode;$('company-avatar').textContent=state.company.name.slice(0,1);$('question-display').textContent=`你问：${report.question}`;$('core-answer').textContent=report.answer;$('last-price').textContent=fmt(q.last_price);$('price-change').textContent=num(q.price_change_ratio_pct)===null?'行情缺失':`${q.price_change_ratio_pct>=0?'上涨':'下跌'} ${pct(q.price_change_ratio_pct)}`;$('return-60').textContent=pct(m.signals?.return60);$('drawdown-60').textContent=pct(m.signals?.maxDrawdown60);$('causal-chain').innerHTML=report.chain.map((item,index)=>`<article class=\"cause-node ${item.state}\"><div class=\"cause-index\">${String(index+1).padStart(2,'0')}</div><div><span>${({support:'支持当前判断',counter:'需要反过来看',unknown:'还没有答案'})[item.state]}</span><h3>${item.title}</h3><p>${item.body}</p><button data-detail=\"${item.detailTarget}\">${item.evidence}，查看原始证据</button></div></article>`).join('');$('next-action-text').textContent=report.nextAction;$('freshness').textContent=`行情更新于 ${new Date(state.bundle.generatedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})} · 财务截至 ${health.financialPeriod||'未知报告期'}`}\nfunction renderProfessionalEvidence(){renderPriceChart();renderFinancial();renderLineage()}\nfunction renderAll(){renderQuestionReport();renderProfessionalEvidence()}\nfunction selectCompany(code,name){state.company={thscode:code,name:name||code};$('stock-search').value=state.company.name;$('search-results').hidden=true;loadResearch()}\n$('search-button').addEventListener('click',searchStocks);$('stock-search').addEventListener('keydown',e=>{if(e.key==='Enter')searchStocks()});$('search-results').addEventListener('click',e=>{const b=e.target.closest('[data-code]');if(b)selectCompany(b.dataset.code,b.dataset.name)});document.querySelectorAll('.quick-stocks button').forEach(b=>b.addEventListener('click',()=>selectCompany(b.dataset.code,b.dataset.name)));$('refresh-button').addEventListener('click',loadResearch);\n$('ask-button').addEventListener('click',()=>{const question=$('research-question').value.trim();if(!question)return;state.question=question;state.bundle?renderQuestionReport():loadResearch();$('health-summary').scrollIntoView({behavior:'smooth'})});\n$('health-route').addEventListener('click',e=>{const detail=e.target.closest('[data-detail]');if(detail){$('professional-evidence').open=true;document.querySelector(`[data-panel=\"${detail.dataset.detail}\"]`)?.click();$('professional-evidence').scrollIntoView({behavior:'smooth'})}});\ndocument.querySelector('.evidence-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-panel]');if(!b)return;document.querySelectorAll('.evidence-tabs button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.evidence-panel').forEach(x=>x.classList.toggle('active',x.id===`${b.dataset.panel}-panel`))});document.querySelector('.range-switch').addEventListener('click',e=>{const b=e.target.closest('[data-range]');if(!b)return;state.range=Number(b.dataset.range);document.querySelectorAll('.range-switch button').forEach(x=>x.classList.toggle('active',x===b));renderPriceChart()});\nfunction drawer(id,open){$(id).classList.toggle('open',open);$(id).setAttribute('aria-hidden',String(!open));document.body.style.overflow=open?'hidden':''}$('method-button').addEventListener('click',()=>drawer('method-modal',true));document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>drawer(b.closest('.drawer').id,false)));loadResearch();\n";
export const healthModelScript = "const STATUS = {\n  positive: '表现较稳',\n  negative: '需要留意',\n  mixed: '出现分化',\n  unknown: '暂无结论',\n};\n\nconst number = value => value === null || value === undefined || value === '--' || !Number.isFinite(Number(value)) ? null : Number(value);\nconst pct = value => number(value) === null ? '—' : `${number(value) >= 0 ? '+' : ''}${number(value).toFixed(1)}%`;\n\nfunction indicators(bundle) {\n  const abilities = bundle?.modules?.indicators?.data?.abilities || [];\n  return Object.fromEntries(abilities.flatMap(group => (group.indicators || []).map(item => [item.index_id, number(item.value)])));\n}\n\nfunction metric(map, names) {\n  for (const name of names) if (map[name] !== undefined) return map[name];\n  return null;\n}\n\nfunction step({ key, number, question, why, state, conclusion, interpretation, primaryEvidence, detailTarget }) {\n  return { key, number, question, why, state, label: STATUS[state], conclusion, interpretation, primaryEvidence, detailTarget };\n}\n\nexport function buildHealthReport(bundle, company) {\n  const modules = bundle?.modules || {};\n  const values = indicators(bundle);\n  const revenue = metric(values, ['calculate_operating_income_yoy_growth_ratio', 'operating_income_yoy_growth_ratio']);\n  const profit = metric(values, ['calculate_parent_holder_net_profit_yoy_growth_ratio', 'net_profit_yoy_growth_ratio']);\n  const cash = metric(values, ['net_profit_cash_content']);\n  const debt = metric(values, ['assets_debt_ratio']);\n  const market = modules.market || {};\n  const return60 = number(market.signals?.return60);\n  const drawdown = number(market.signals?.maxDrawdown60);\n\n  const growthState = revenue === null || profit === null ? 'unknown' : revenue >= 0 && profit >= 0 ? 'positive' : revenue * profit < 0 ? 'mixed' : 'negative';\n  const cashState = cash === null ? 'unknown' : cash >= 100 ? 'positive' : cash >= 60 ? 'mixed' : 'negative';\n  const debtState = debt === null ? 'unknown' : debt <= 60 ? 'positive' : debt <= 70 ? 'mixed' : 'negative';\n  const marketState = return60 === null || drawdown === null ? 'unknown' : return60 >= 0 && drawdown > -15 ? 'positive' : return60 < 0 ? 'negative' : 'mixed';\n\n  const steps = [\n    step({ key: 'earning', number: '01', question: '生意还在增长吗？', why: '收入说明生意规模，利润说明增长有没有真正留下来；两者要一起看。', state: growthState, conclusion: growthState === 'unknown' ? '关键增长数据还不完整' : growthState === 'positive' ? '收入和利润仍在同向增长' : growthState === 'mixed' ? '收入与利润的方向出现分化' : '收入和利润都面临增长压力', interpretation: growthState === 'positive' ? '增长方向一致，但还需继续观察增速是否放缓。' : growthState === 'mixed' ? '只看收入或利润都会失真，需要检查成本、毛利和一次性项目。' : growthState === 'negative' ? '当前增长承压，不代表未来一定继续下降。' : '没有足够证据时，不用旧数据代替最新判断。', primaryEvidence: `收入同比 ${pct(revenue)} · 归母净利润同比 ${pct(profit)}`, detailTarget: 'financial' }),\n    step({ key: 'cash', number: '02', question: '赚到的钱真的收到现金了吗？', why: '利润是会计结果，现金是实际流入；现金跟不上时，利润质量可能需要进一步核实。', state: cashState, conclusion: cash === null ? '暂时无法判断利润的现金含量' : cashState === 'positive' ? '经营现金能够较好覆盖利润' : cashState === 'mixed' ? '利润和现金基本匹配，但不算充裕' : '利润转成现金的能力偏弱', interpretation: cashState === 'positive' ? '每 100 元利润对应的经营现金不少于 100 元，现金质量相对扎实。' : cashState === 'unknown' ? '需要经营现金流与净利润的同口径数据。' : '需要继续检查应收账款、存货和付款节奏。', primaryEvidence: `每 100 元利润对应经营现金 ${cash === null ? '—' : cash.toFixed(0) + ' 元'}`, detailTarget: 'financial' }),\n    step({ key: 'safety', number: '03', question: '公司的财务负担重吗？', why: '负债不是越少越好，但过高会降低公司应对行业波动的余地。', state: debtState, conclusion: debt === null ? '暂时无法判断负债水平' : debtState === 'positive' ? '整体负债水平相对温和' : debtState === 'mixed' ? '负债水平需要结合行业理解' : '负债水平偏高，需要重点核实', interpretation: debtState === 'mixed' ? '制造业常有经营性负债，不能只凭一个比例判定风险。' : debtState === 'positive' ? '当前比例留有一定缓冲，但仍要看短期偿债和利息压力。' : debtState === 'negative' ? '需要进一步区分有息负债与经营性负债。' : '缺失时保持未知，不用行业印象代替数据。', primaryEvidence: `每 100 元资产中负债 ${debt === null ? '—' : debt.toFixed(1) + ' 元'}`, detailTarget: 'financial' }),\n    step({ key: 'market', number: '04', question: '市场最近怎么看它？', why: '价格反映市场近期态度，不等于公司价值；趋势和回撤要放在一起看。', state: marketState, conclusion: return60 === null ? '近期市场数据暂不可用' : marketState === 'positive' ? '近期价格表现相对平稳' : marketState === 'negative' ? '近期价格表现偏弱' : '价格有表现，但波动也较明显', interpretation: '这是历史市场表现，不是未来涨跌预测；请和基本面变化对照阅读。', primaryEvidence: `近 60 日 ${pct(return60)} · 最大回撤 ${pct(drawdown)}`, detailTarget: 'market' }),\n    step({ key: 'unknowns', number: '05', question: '还有哪些事现在不能下结论？', why: '好的研究不仅说知道什么，也要明确哪些关键证据仍然缺失。', state: 'unknown', conclusion: '估值、同行位置和最新事件仍待补充', interpretation: '没有同日估值、可比公司分位和公告原文时，不判断“贵不贵”或事件影响。', primaryEvidence: '3 类关键证据尚未接入', detailTarget: 'lineage' }),\n  ];\n\n  const counts = steps.reduce((acc, item) => ({ ...acc, [item.state]: (acc[item.state] || 0) + 1 }), {});\n  const incomplete = [modules.market, modules.financials, modules.indicators].some(module => !module || module.status !== 'ok');\n  const attention = steps.filter(item => item.state === 'negative' || item.state === 'mixed');\n  const vitalUnknowns = steps.slice(0, 4).filter(item => item.state === 'unknown').length;\n  const financialDates = [...(modules.financials?.income || []), ...(modules.financials?.balance || []), ...(modules.financials?.cashflow || [])]\n    .map(row => row?.period_end_ms || row?.period_end || row?.end_date_ms).filter(Boolean).map(Number).filter(Number.isFinite);\n  const financialPeriod = financialDates.length ? new Date(Math.max(...financialDates)).toISOString().slice(0, 10) : null;\n  const summary = vitalUnknowns >= 2\n    ? `${company.name} 目前不足以概括基本面，先补齐关键体征再判断。`\n    : incomplete\n    ? `${company.name} 的证据还不完整，先看已确认部分，再补齐缺失数据。`\n    : attention.length\n      ? `${company.name} 的基本面有支撑，但有 ${attention.length} 项值得继续核实。`\n      : `${company.name} 当前几项核心体征较平稳，但仍有未知信息需要补充。`;\n  const actions = [\n    ...(incomplete ? ['补齐未成功返回的数据模块，再更新体检结论。'] : []),\n    ...attention.slice(0, 2).map(item => `继续核实「${item.question.replace('？', '')}」背后的变化原因。`),\n    '补充同行估值和最新公告后，再形成更完整判断。',\n  ].slice(0, 3);\n\n  return { company, summary, counts, steps, actions, financialPeriod };\n}\n\nfunction questionRoute(question='') {\n  if (/(能买吗|买不买|该买|会涨|涨不涨|目标价|卖出|卖吗)/.test(question)) return 'investment-decision';\n  if (/(估值|贵不贵|便宜|市盈率|市净率|同行|同业)/.test(question)) return 'valuation-peer';\n  if (/(现金流|回款|负债|偿债|杠杆|债务|资金链)/.test(question)) return 'cash-debt';\n  if (/(增长|收入|利润|增速|成长)/.test(question)) return 'growth';\n  return 'clarify';\n}\n\nconst unknownStep=(title,body,evidence='当前数据尚未覆盖',detailTarget='lineage')=>({role:'unknown',state:'unknown',title,body,evidence,detailTarget});\n\nexport function buildQuestionReport(bundle, company, question) {\n  const values = indicators(bundle);\n  const revenue = metric(values, ['calculate_operating_income_yoy_growth_ratio', 'operating_income_yoy_growth_ratio']);\n  const profit = metric(values, ['calculate_parent_holder_net_profit_yoy_growth_ratio', 'net_profit_yoy_growth_ratio']);\n  const cash = metric(values, ['net_profit_cash_content']);\n  const debt = metric(values, ['assets_debt_ratio']);\n  const market = bundle?.modules?.market?.signals || {};\n  const route=questionRoute(question);\n  const growthKnown = revenue !== null && profit !== null;\n  if(route==='clarify') return {route,question,answer:`请把问题说得更具体一些：你可以问 ${company.name} 的增长、现金流与负债，或估值与同行位置。`,chain:[unknownStep('先确定你真正关心的事','“这家公司怎么样”范围太大，直接生成结论容易把不同问题混在一起。'),unknownStep('选择一个判断方向','增长回答生意是否扩张；现金流与负债回答财务承受力；估值回答价格是否有可比依据。')],nextAction:'从增长、现金流与负债、估值与同行中选择一个方向'};\n  if(route==='investment-decision') return {route,question,answer:`这个工具不能替你判断 ${company.name} 能不能买，也不能预测会不会涨；它只能把已知证据、反证和缺口列清楚。`,chain:[unknownStep('先划清判断边界','买卖决定取决于个人目标、期限和风险承受力，不能由一组公司指标直接推出。','产品合规边界'),{role:'evidence',state:growthKnown?'support':'unknown',title:'目前能确认什么',body:growthKnown?`收入同比 ${pct(revenue)}，归母净利润同比 ${pct(profit)}；这是经营事实，不是涨跌信号。`:'最新收入或利润增速没有完整返回。',evidence:'最近报告期的增长指标',detailTarget:'financial'},unknownStep('还缺什么','缺少同日估值、同行比较、最新公告以及你的持有期限和风险边界，不能形成个人买卖结论。'),{role:'next',state:'unknown',title:'下一步怎么做',body:'先分别核实基本面、估值和风险，再由你按自己的目标决定是否继续研究。',evidence:'待完成的研究步骤',detailTarget:'lineage'}],nextAction:'先选择增长、现金流与负债或估值问题继续核实'};\n  if(route==='valuation-peer') return {route,question,answer:`目前缺少 ${company.name} 的同日估值和可比公司分位，不能可靠判断贵不贵。`,chain:[unknownStep('先看公司值多少钱','当前没有同日市盈率、市净率或企业价值倍数，不能用过期数字代替。','同日估值数据尚未接入'),{role:'context',state:growthKnown?'support':'unknown',title:'估值要和经营状态一起看',body:growthKnown?`收入同比 ${pct(revenue)}，归母净利润同比 ${pct(profit)}；增速不同，合理估值区间也会不同。`:'最新增长数据不完整，估值背景也缺一块。',evidence:'最近报告期的增长指标',detailTarget:'financial'},unknownStep('再和谁比较','缺少同一日期、同一口径的家电与制造业可比公司数据，不能用单家公司倍数直接下结论。','同行估值分位尚未接入'),unknownStep('哪些差异会误导比较','业务结构、海外收入、资本结构和一次性损益都会改变估值可比性。'),{role:'next',state:'unknown',title:'下一步该查什么',body:'补齐同日估值，再选业务结构接近的同行，统一口径比较历史分位和增长预期。',evidence:'待完成的估值研究',detailTarget:'lineage'}],nextAction:'补齐同日估值和可比公司分位'};\n  if(route==='cash-debt') return {route,question,answer:cash===null&&debt===null?`${company.name} 的现金流和负债数据不完整，现在不能判断财务承受力。`:cash!==null&&debt!==null?`${company.name} 每 100 元利润对应约 ${cash.toFixed(0)} 元经营现金，每 100 元资产中约有 ${debt.toFixed(1)} 元负债，需要把回款质量和负债结构一起看。`:`${company.name} 只有部分现金流或负债证据，暂时不能形成完整判断。`,chain:[{role:'phenomenon',state:cash===null?'unknown':cash>=100?'support':'counter',title:'利润有没有变成现金',body:cash===null?'经营现金与利润的对应关系暂时未知。':`每 100 元利润对应约 ${cash.toFixed(0)} 元经营现金。`,evidence:'经营现金流与净利润的同口径比较',detailTarget:'financial'},{role:'reason',state:debt===null?'unknown':debt<=60?'support':'counter',title:'资产背了多少负债',body:debt===null?'负债数据没有完整返回。':`每 100 元资产中约有 ${debt.toFixed(1)} 元负债；还需区分经营性负债和有息负债。`,evidence:'最近报告期的资产与负债',detailTarget:'financial'},unknownStep('短期压力还不知道','缺少债务期限、利息支出和受限资金明细，不能只凭资产负债率判断安全。','债务结构尚未接入'),{role:'counter',state:'unknown',title:'什么会推翻当前理解',body:'若应收账款和存货持续占用现金，或短债集中到期，即使利润为正，资金压力也可能上升。',evidence:'应收、存货与债务期限待核实',detailTarget:'financial'},{role:'next',state:'unknown',title:'下一步该查什么',body:'回到现金流量表和附注，核实应收、存货、有息负债及一年内到期债务。',evidence:'待完成的财务核查',detailTarget:'financial'}],nextAction:'核实应收、存货和有息负债期限'};\n  const answer = !growthKnown\n    ? `${company.name} 的最新增长数据不完整，现在还不能判断增长是否稳定。`\n    : revenue >= 0 && profit >= 0\n      ? `${company.name} 仍在增长，但利润增速低于收入，增长的含金量需要继续看。`\n      : revenue * profit < 0\n        ? `${company.name} 的收入和利润方向不一致，增长已经出现分化。`\n        : `${company.name} 的收入和利润都在承压，目前看不到稳定增长。`;\n  const chain = [\n    { role:'phenomenon', state:growthKnown?(revenue>=0&&profit>=0?'support':'counter'):'unknown', title:'先看发生了什么', body:growthKnown?`收入同比 ${pct(revenue)}，归母净利润同比 ${pct(profit)}。`:'最新收入或利润增速没有完整返回。', evidence:'增长指标，财务截至最近报告期', detailTarget:'financial' },\n    { role:'reason', state:cash===null?'unknown':cash>=100?'support':'counter', title:'再看增长有没有变成现金', body:cash===null?'经营现金与利润的对应关系暂时未知。':cash>=100?`每 100 元利润对应约 ${cash.toFixed(0)} 元经营现金，利润有现金支撑。`:`每 100 元利润只对应约 ${cash.toFixed(0)} 元经营现金，利润回款需要核实。`, evidence:'经营现金流与净利润的同口径比较', detailTarget:'financial' },\n    { role:'counter', state:debt===null?'unknown':debt>60?'counter':'support', title:'有没有相反证据', body:debt===null?'负债数据没有完整返回。':debt>60?`每 100 元资产中约有 ${debt.toFixed(1)} 元负债。制造业经营性负债较多，不能直接判定风险。`:`每 100 元资产中约有 ${debt.toFixed(1)} 元负债，当前没有明显的高杠杆反证。`, evidence:'资产与负债，最近报告期', detailTarget:'financial' },\n    { role:'unknown', state:'unknown', title:'哪一环还不知道', body:'缺少同日同行比较和最新公告原文，暂时无法判断增长在行业里处于什么位置，也无法解释突发事件。', evidence:'同行与事件数据尚未接入', detailTarget:'lineage' },\n    { role:'impact', state:number(market.return60)===null?'unknown':number(market.return60)<0?'counter':'support', title:'市场怎样消化这些信息', body:number(market.return60)===null?'近期价格数据暂不可用。':`近 60 日价格变化 ${pct(market.return60)}，期间最大回撤 ${pct(market.maxDrawdown60)}。这是市场反应，不是未来预测。`, evidence:'前复权日线，确定性计算', detailTarget:'market' },\n    { role:'next', state:'unknown', title:'下一步该查什么', body:growthKnown?'先比较同行的收入和利润增速，再回到财报核实毛利率、应收账款和一次性损益。':'先补齐最新财务数据，再判断增长方向。', evidence:'待完成的研究步骤', detailTarget:'financial' },\n  ];\n  return { route, question, answer, chain, nextAction: growthKnown?'比较同行并查看原始财报':'补齐最新财务数据' };\n}\n";
export const diagnosisModelScript = "const DIRECTIONS=new Set(['positive','negative','conflicting','missing']);\nconst STATUSES=new Set(['fact','inference','unverified']);\nconst DIMENSIONS=['operating_quality','financial_trend','valuation','market_characteristics','industry_position','material_events','risk'];\n\nconst n=value=>value===null||value===undefined||value===''||!Number.isFinite(Number(value))?null:Number(value);\nconst pct=value=>n(value)===null?'未取得':`${n(value)>=0?'+':''}${n(value).toFixed(1)}%`;\nconst valuesFrom=bundle=>Object.fromEntries((bundle?.modules?.indicators?.data?.abilities||[]).flatMap(group=>(group.indicators||[]).map(item=>[item.index_id,n(item.value)])));\nconst pick=(values,...keys)=>{for(const key of keys)if(values[key]!==undefined)return values[key];return null};\n\nfunction intentOf(question=''){\n  if(/能买吗|买不买|会涨|涨不涨|目标价|卖出/.test(question))return'investment_boundary';\n  if(/估值|贵不贵|便宜|市盈率|市净率|同行/.test(question))return'valuation';\n  if(/现金流|回款|负债|偿债|杠杆|债务/.test(question))return'cash_debt';\n  return'growth';\n}\n\nconst dimensionLabels={operating_quality:'经营质量',financial_trend:'财务趋势',valuation:'估值',market_characteristics:'行情特征',industry_position:'行业位置',material_events:'重要事件',risk:'风险'};\nconst dimensionOrders={\n  growth:['operating_quality','financial_trend','industry_position','material_events','risk','valuation','market_characteristics'],\n  cash_debt:['financial_trend','risk','operating_quality','industry_position','material_events','valuation','market_characteristics'],\n  valuation:['valuation','industry_position','financial_trend','risk','market_characteristics','operating_quality','material_events'],\n  investment_boundary:['operating_quality','financial_trend','valuation','risk','industry_position','material_events','market_characteristics'],\n};\nconst reasons={\n  growth:{operating_quality:'问题涉及增长是否形成经营成果',financial_trend:'需要核对收入、利润与现金的变化关系',industry_position:'需要区分公司变化与行业共同变化'},\n  cash_debt:{financial_trend:'问题直接涉及现金与负债变化',risk:'需要核对偿债与资金压力',operating_quality:'现金占用可能来自经营环节'},\n  valuation:{valuation:'问题直接涉及当前估值',industry_position:'估值需要同口径同行参照',financial_trend:'增长与盈利趋势影响估值解释'},\n  investment_boundary:{operating_quality:'只呈现可验证经营事实',financial_trend:'只呈现可验证财务变化',valuation:'买卖判断需要估值证据'},\n};\n\nfunction selectedDimensions(intent,bundle){\n  const order=dimensionOrders[intent]||dimensionOrders.growth;\n  return order.map((dimension,index)=>({\n    dimension,label:dimensionLabels[dimension],priority:index+1,\n    relevanceReason:reasons[intent]?.[dimension]||'作为补充诊断维度保留',\n    availability:['valuation','industry_position','material_events'].includes(dimension)?'unavailable':bundle?.modules?'partial':'unavailable',\n  }));\n}\n\nfunction proposition(input){\n  if(!DIRECTIONS.has(input.evidenceDirection)||!STATUSES.has(input.epistemicStatus))throw new Error('invalid proposition state');\n  return {evidenceRefs:[],limitations:[],...input};\n}\n\nexport function buildDiagnosisReport(bundle,company,question=''){\n  const intent=intentOf(question);\n  const companyType=company?.companyType||'general_corporate';\n  const limitations=companyType==='general_corporate'?['公司类型待验证，当前使用通用公司诊断顺序。']:[];\n  const values=valuesFrom(bundle);\n  const revenue=pick(values,'calculate_operating_income_yoy_growth_ratio','operating_income_yoy_growth_ratio');\n  const profit=pick(values,'calculate_parent_holder_net_profit_yoy_growth_ratio','net_profit_yoy_growth_ratio');\n  const cash=pick(values,'net_profit_cash_content');\n  const debt=pick(values,'assets_debt_ratio');\n  const growthKnown=revenue!==null&&profit!==null;\n  const propositions=[];\n\n  if(growthKnown){\n    const direction=revenue>=0&&profit>=0?'positive':revenue*profit<0?'conflicting':'negative';\n    propositions.push(proposition({id:'growth-fact',dimension:'operating_quality',title:'收入与利润的变化方向',statement:`营业收入同比 ${pct(revenue)}，归母净利润同比 ${pct(profit)}。`,evidenceDirection:direction,epistemicStatus:'fact',evidenceRefs:['metric-revenue-growth','metric-profit-growth']}));\n    propositions.push(proposition({id:'growth-inference',dimension:'operating_quality',title:'增长关系的分析解释',statement:revenue*profit<0?'收入与利润方向不一致，增长结构需要进一步核对。':profit<revenue?'利润增速低于收入增速，需要核对成本与费用变化。':'收入与利润方向一致，但仍需同行数据确认相对位置。',evidenceDirection:direction,epistemicStatus:'inference',evidenceRefs:['growth-fact'],limitations:['未取得同口径同行增速']}));\n  }else propositions.push(proposition({id:'growth-missing',dimension:'operating_quality',title:'收入与利润变化',statement:'最新收入或利润增速未完整取得。',evidenceDirection:'missing',epistemicStatus:'unverified',limitations:['指标模块缺失或获取失败']}));\n\n  if(cash!==null)propositions.push(proposition({id:'cash-fact',dimension:'financial_trend',title:'利润与经营现金的对应关系',statement:`每 100 元利润对应约 ${cash.toFixed(0)} 元经营现金。`,evidenceDirection:cash>=100?'positive':'negative',epistemicStatus:'fact',evidenceRefs:['metric-cash-content']}));\n  else propositions.push(proposition({id:'cash-missing',dimension:'financial_trend',title:'利润与经营现金的对应关系',statement:'经营现金与利润的同口径数据未取得。',evidenceDirection:'missing',epistemicStatus:'unverified',limitations:['现金质量指标缺失']}));\n  if(debt!==null)propositions.push(proposition({id:'debt-fact',dimension:'risk',title:'资产负债关系',statement:`每 100 元资产中约有 ${debt.toFixed(1)} 元负债。`,evidenceDirection:debt>70?'negative':'positive',epistemicStatus:'fact',evidenceRefs:['metric-debt-ratio'],limitations:['资产负债率不区分经营性负债与有息负债']}));\n\n  propositions.push(proposition({id:'industry-unverified',dimension:'industry_position',title:'同行位置',statement:'同日、同口径的同行数据尚未取得。',evidenceDirection:'missing',epistemicStatus:'unverified',limitations:['缺少可比公司样本与比较日期']}));\n  propositions.push(proposition({id:'valuation-unverified',dimension:'valuation',title:'估值位置',statement:'同日估值与历史分位尚未取得。',evidenceDirection:'missing',epistemicStatus:'unverified',limitations:['不能使用过期价格替代当前估值']}));\n\n  const summary=intent==='investment_boundary'\n    ?'本产品不提供买卖建议，也不能预测确定性涨跌；以下仅整理可验证的经营、财务与估值证据。'\n    :growthKnown?`已确认收入同比 ${pct(revenue)}、归母净利润同比 ${pct(profit)}；同行、估值与事件证据仍需补充。`:'关键财务证据未完整取得，当前只展示可验证内容和缺失项。';\n  const dates=[...(bundle?.modules?.financials?.income||[]),...(bundle?.modules?.financials?.balance||[]),...(bundle?.modules?.financials?.cashflow||[])].map(x=>n(x.period_end_ms||x.period_end||x.end_date_ms)).filter(x=>x!==null);\n  return {\n    company,companyType,intent,question,\n    asOf:{generatedAt:bundle?.generatedAt||null,financialPeriod:dates.length?new Date(Math.max(...dates)).toISOString().slice(0,10):null},\n    selectedDimensions:selectedDimensions(intent,bundle),summary,propositions,\n    verificationQuestions:['补充同口径同行增速后确认相对位置','核对最新公告中是否存在一次性影响','取得同日估值与历史分位'],\n    limitations,\n  };\n}\n\nexport { DIMENSIONS };\n";
